  CLEAR_BIT(hsmartcard->Instance->CR3, USART_CR3_EIE);

  /* Check if a Transmit process is ongoing or not. If not disable ERR IT */
  if (hsmartcard->gState == HAL_SMARTCARD_STATE_READY)
